import React from 'react';
import {Link} from 'react-router-dom';
import {motion} from 'framer-motion';
import Seo from '../components/Seo';
import ProjectCard from '../components/ProjectCard';
import {projects,capabilities} from '../data/site';
export default function Home(){return <>
 <Seo description="Beyond31 est le portfolio technologique de Huriel Nguimbi : produits numériques, web, mobile, design et expérimentations techniques." schema={{'@context':'https://schema.org','@type':'Person',name:'Huriel Nguimbi',url:'https://beyond31.online',knowsAbout:['Web development','Flutter','Product design','Embedded systems']}}/>
 <section className="home-hero"><div className="hero-rail"><span>CREATIVE TECHNOLOGY</span><span>PORTFOLIO / LAB</span></div><div className="hero-main"><motion.p className="mono hero-note" initial={{opacity:0}} animate={{opacity:1}}>Huriel Nguimbi — Poitiers</motion.p><motion.h1 initial={{opacity:0,y:36}} animate={{opacity:1,y:0}} transition={{duration:.8}}>Je transforme ma curiosité<br/>en <em>produits qui existent.</em></motion.h1><div className="hero-sub"><p>Beyond31 rassemble mes projets web, mobiles et techniques. Pas une vitrine de concepts : un endroit pour suivre ce que je construis, teste et améliore.</p><Link className="signal-link" to="/projets"><span>Voir les projets</span><b>↘</b></Link></div></div><div className="hero-object" aria-hidden="true"><div className="shape shape-a"/><div className="shape shape-b"/><span>31</span><small>BUILD / TEST / LEARN</small></div></section>
 <section className="ticker" aria-label="Domaines explorés"><div>WEB <i/> MOBILE <i/> PRODUCT <i/> UI/UX <i/> EMBEDDED <i/> SEO <i/> WEB <i/> MOBILE <i/> PRODUCT <i/> UI/UX</div></section>
 <section className="section projects-home"><div className="section-head"><p className="mono">01 / SELECTED WORK</p><h2>Trois projets réels.<br/><em>Trois problèmes différents.</em></h2><Link to="/projets">Tout voir ↗</Link></div><div className="project-grid">{projects.map((p,i)=><ProjectCard key={p.slug} p={p} large={i===0}/>)}</div></section>
 <section className="section capability-preview"><div className="section-head"><p className="mono">02 / CAPABILITIES</p><h2>Ce que je sais déjà<br/><em>mettre en mouvement.</em></h2><Link to="/expertise">Détailler ↗</Link></div><div className="cap-preview-grid">{capabilities.slice(0,4).map(c=><div key={c.n} className="cap-preview"><span className="mono">{c.n}</span><h3>{c.title}</h3><p>{c.desc}</p><div>{c.tools.slice(0,3).map(t=><span key={t}>{t}</span>)}</div></div>)}</div></section>
 <section className="manifesto-strip"><p>Beyond31 n’essaie pas de paraître grand.</p><h2>Le but est de <em>devenir solide</em>, projet après projet.</h2><Link to="/studio">Pourquoi Beyond31 ↗</Link></section>
 </>}
